import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788283396000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. There is no config file, and nothing is read from disk.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>HETZNER_API_TOKEN</code></td><td>yes</td><td>—</td><td>Hetzner Cloud API token, project-scoped</td></tr><tr><td><code>HETZNER_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td><code>true</code> registers only the read tools</td></tr><tr><td><code>HETZNER_API_BASE_URL</code></td><td>no</td><td><code>https://api.hetzner.cloud/v1</code></td><td>Override the API base URL</td></tr></tbody></table><p>The full descriptions are in the <a href="/reference/environment">environment reference</a>.</p><h2 id="hetzner-api-token" tabindex="-1"><code>HETZNER_API_TOKEN</code> <a class="header-anchor" href="#hetzner-api-token" aria-label="Permalink to “HETZNER_API_TOKEN”">​</a></h2><p>A Hetzner Cloud API token from <strong>Security → API tokens</strong> in the project that holds your zones. It is sent as a <code>Bearer</code> header on every request.</p><p>Pass it through your MCP client&#39;s <code>env</code> block. Not on a command line, where <code>ps</code> shows it to every user on the machine, and not in a file you might commit.</p><p>The server reads it once at startup and then <strong>deletes it from <code>process.env</code></strong>, so a later crash report, a Node diagnostic report or a dependency that dumps the environment finds nothing there.</p><h2 id="read-only-mode" tabindex="-1">Read-only mode <a class="header-anchor" href="#read-only-mode" aria-label="Permalink to “Read-only mode”">​</a></h2><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">HETZNER_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>Accepted as <code>true</code>, <code>1</code> or <code>yes</code>, case-insensitively.</p><p>This does not reject write calls — it never registers the write tools in the first place. <code>tools/list</code> returns seven tools, and a client asking for <code>delete_zone</code> gets &quot;tool not found&quot; from the protocol layer. There is no code path from a write request to the API.</p><p>Pair it with a read-only Hetzner token for defence in depth: the token stops the API from accepting a write, and read-only mode stops the model from ever seeing a tool that could attempt one.</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;hetzner-dns&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;command&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;npx&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;args&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;-y&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;hetzner-dns-mcp&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">],</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">      &quot;env&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">        &quot;HETZNER_API_TOKEN&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;your-read-only-token&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">,</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">        &quot;HETZNER_READ_ONLY&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;true&quot;</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">      }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">    }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Two servers, two roles</p><p>Nothing stops you registering the same package twice — once read-only for everyday questions, once with write access under a different name for the sessions where you actually intend to change something.</p></div><h2 id="turning-the-approval-dialog-off" tabindex="-1">Turning the approval dialog off <a class="header-anchor" href="#turning-the-approval-dialog-off" aria-label="Permalink to “Turning the approval dialog off”">​</a></h2><p>The irreversible tools ask a person through MCP elicitation before they act. <code>ELICITATION=false</code> takes them to the two-call token instead. It does not remove the guard; there is no setting in which a guarded call goes unannounced.</p><p>The variable deliberately carries no <code>HETZNER_</code> prefix, which means it reaches every MCP server in the same environment, and — unlike <code>HETZNER_READ_ONLY</code> — a value it does not recognise <strong>stops the server</strong> rather than failing open. See <a href="/guide/approval">Asking a person</a>.</p><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Read-only mode is one cut, along a line this server drew for you. The other two variables let you draw your own:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">HETZNER_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">HETZNER_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">list_*,get_zone,set_records</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">HETZNER_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">delete_zone,import_zonefile</span></span></code></pre></div><p>Why bother, when all twenty-two work: a model chooses the right tool far more reliably from a handful than from a long list, and every tool it can see costs context on every single request. If this is the only MCP server in a session, twenty-two is fine. If it is one of six, it is not.</p><p><strong>The syntax.</strong> Comma-separated entries. An entry is either an exact tool name or a prefix with a trailing <code>*</code> — <code>list_*</code> matches every tool whose name starts with <code>list_</code>. Entries are trimmed and case-insensitive, empty ones are ignored, and an empty value counts as unset. Nothing else is a pattern: <code>*_zone</code> and <code>list_*_x</code> are rejected rather than silently matching nothing.</p><p><strong><code>essential</code></strong> is a curated preset of eight, covering the two things people actually come here to do — read a zone, change a record:</p><p><code>list_zones</code> · <code>get_zone</code> · <code>list_rrsets</code> · <code>get_rrset</code> · <code>create_rrset</code> · <code>set_records</code> · <code>delete_rrset</code> · <code>export_zonefile</code></p><p><code>set_records</code> subsumes <code>add_records</code> and <code>remove_records</code>, and <code>export_zonefile</code> answers &quot;show me everything&quot; in one call. Left out on purpose: creating and deleting whole zones, importing a zone file, the TTL and protection tools, and the asynchronous action polling. It composes — <code>essential,update_zone</code> adds one back, and <code>HETZNER_DENY_TOOLS</code> takes one away.</p><p><strong>Both together.</strong> <code>HETZNER_ALLOW_TOOLS</code> decides what is in; <code>HETZNER_DENY_TOOLS</code> is then subtracted from the result. With only a deny list, everything else stays.</p><p><strong>A name that matches nothing stops the server</strong>, with the offending entry and the list of real names. That is deliberate: the alternative is a tool quietly missing from <code>tools/list</code>, and nobody traces an absence back to an environment variable. The same applies to a pattern that matches no tool, which is what catches <code>delet_*</code>.</p><p><strong>With read-only mode</strong>, the write tools are not registered at all, so naming one explicitly in <code>HETZNER_ALLOW_TOOLS</code> is an error that says so — rather than calling a tool unknown when it plainly exists. A <em>pattern</em> that covers write tools is fine and simply contributes nothing, which is what makes <code>get_*,create_*</code> a usable template for both kinds of deployment; and <code>HETZNER_ALLOW_TOOLS=essential</code> narrows to the read half of the preset.</p><div class="tip custom-block"><p class="custom-block-title">It is the same cut, not a second one</p><p>A filtered tool is never registered, so it is absent from <code>tools/list</code> and unknown to <code>tools/call</code> alike — exactly what <code>HETZNER_READ_ONLY</code> does to a write tool. There is no &quot;hidden but callable&quot; state to reason about.</p></div><h2 id="hetzner-api-base-url" tabindex="-1"><code>HETZNER_API_BASE_URL</code> <a class="header-anchor" href="#hetzner-api-base-url" aria-label="Permalink to “HETZNER_API_BASE_URL”">​</a></h2><p>Only useful for testing against a local mock. It is validated before anything is sent:</p><ul><li>must parse as a URL, and be <code>https</code> — <code>http</code> is accepted only for <code>localhost</code>, <code>127.0.0.1</code> and <code>[::1]</code></li><li>must not contain credentials (<code>https://user:pass@…</code> is rejected)</li><li>a non-default host produces a warning on stderr, because your token is about to be sent there</li></ul><p>A value that fails these checks exits the process rather than starting a server that would leak the token on its first call. The value itself is never printed back, since a malformed one can carry a <code>user:token@</code> part.</p><h2 id="timeouts-and-limits" tabindex="-1">Timeouts and limits <a class="header-anchor" href="#timeouts-and-limits" aria-label="Permalink to “Timeouts and limits”">​</a></h2><p>These are not configurable, and are listed so you know what to expect:</p><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th></tr></thead><tbody><tr><td>Request timeout</td><td>30 seconds</td></tr><tr><td>Redirects</td><td>refused (<code>redirect: &#39;error&#39;</code>)</td></tr><tr><td>Confirmation token TTL</td><td>5 minutes, single use</td></tr><tr><td>Pending tokens kept</td><td>100, oldest evicted</td></tr><tr><td>Single value in a result</td><td>truncated at 4 000 characters</td></tr><tr><td>Whole result</td><td>truncated at 200 000 characters</td></tr><tr><td>Upstream error body</td><td>truncated at 2 000 characters; HTML dropped</td></tr></tbody></table><p>If a list tool truncates, narrow it with <code>per_page</code> and <code>page</code> rather than retrying — the caps exist because a large zone would otherwise fill the context window in a single call.</p>`,38)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};